set-variable.value:
@{
    var candidate = context.Request.Headers.GetValueOrDefault("traceparent", string.Empty).Trim().ToLowerInvariant();
    if (System.Text.RegularExpressions.Regex.IsMatch(candidate, "^00-[a-f0-9]{32}-[a-f0-9]{16}-0[01]$"))
    {
      return candidate;
    }
    return "00-" + Guid.NewGuid().ToString("N") + "-" + Guid.NewGuid().ToString("N").Substring(0, 16) + "-01";
  }
